'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const RULES=Logic.ruleInfo;
const problems=PROBLEMS;let saved={};try{saved=JSON.parse(localStorage.getItem('logicWorkshopClassV2')||'{}')}catch{}let drafts=saved.drafts||{},solved=new Set(saved.solved||[]),current=Number.isInteger(saved.current)&&saved.current>=0&&saved.current<problems.length?saved.current:0,filter='전체',sourceFilter='전체',state,history=[];
function persist(){drafts[current]={state,history};try{localStorage.setItem('logicWorkshopClassV2',JSON.stringify({drafts,solved:[...solved],current}))}catch{$('feedback').textContent='저장 공간을 사용할 수 없습니다. 현재 세션에서 계속 연습할 수 있습니다.'}}
function feedback(msg,type='success'){$('feedback').className=type;$('feedback').textContent=msg}
function renderList(){let list=problems.filter(p=>(filter==='전체'||p.level===filter)&&(sourceFilter==='전체'||p.source===sourceFilter));$('problemList').innerHTML=list.map(p=>`<button class="problem-item ${p.id===current?'chosen':''}" data-id="${problems.indexOf(p)}" aria-current="${problems.indexOf(p)===current?'true':'false'}"><span class="problem-index">${String(problems.indexOf(p)+1).padStart(2,'0')}</span><span><span class="problem-name">${esc(p.title)}</span><span class="problem-meta">${esc(p.source+(p.page?' · p.'+p.page:''))} · ${esc(p.level)}</span></span>${solved.has(p.id)?'<span class="completion" aria-label="완료">✓</span>':''}</button>`).join('');$('problemTotal').textContent=problems.length+'문제';$('solvedCount').innerHTML=solved.size+'<span> / '+problems.length+'</span>';$('progressBar').style.width=solved.size/problems.length*100+'%'}
function render(){let p=problems[current],allowed=new Set(p.allowed);$('levelLabel').textContent=p.level;$('exerciseNumber').textContent=String(current+1).padStart(2,'0')+' / '+String(problems.length).padStart(2,'0');$('exerciseTitle').textContent=p.title;$('goalLabel').textContent=p.kind==='타당성'?'증명할 논증':p.kind==='기호화 연습'?'기호화한 논증을 증명':'증명할 명제';$('sequent').innerHTML=(p.premises.length?p.premises.map(f=>esc(Logic.format(Logic.parse(f)))).join(', '):'')+'<span class="sequent-turn">⊢</span>'+esc(Logic.format(Logic.parse(p.goal)));$('sourceLink').innerHTML=p.page?`<a target="_blank" rel="noopener" href="sources/${p.source==='핸드아웃 4'?'handout-4':'handout-5'}.pdf#page=${p.page}">원문 ${esc(p.source)} p.${p.page} ↗</a>`:p.source==='창작'?'<span>추가 연습</span>':'';$('proofLines').innerHTML=state.lines.map((l,i)=>`<div class="proof-row ${l.path.length&&!Logic.prefix(l.path,state.stack)?'closed':''}"><span class="line-num">${i+1}</span><span class="line-formula" style="padding-left:${l.path.length*14}px"><span class="${l.path.length?'scope-bar':''}">${esc(Logic.format(l.a))}</span></span><span class="line-reason">${esc(l.rule)} ${esc(l.refs)}</span></div>`).join('');$('emptyProof').hidden=!!state.lines.length;$('scopeLabel').textContent=state.stack.length?'가정 범위 · 깊이 '+state.stack.length:'기본 범위';$('closeAssumption').disabled=!state.stack.length;$('undo').disabled=!history.length;const select=$('ruleInput'),prior=select.value;select.innerHTML=RULES.filter(r=>allowed.has(r[0])).map(r=>`<option value="${esc(r[0])}">${esc(r[0])} · ${esc(r[1])}</option>`).join('');if(allowed.has(prior))select.value=prior;renderList()}
function load(i){current=i;let d=drafts[i];state=d?d.state:Logic.initial(problems[i].premises);history=d?d.history:[];$('feedback').className='';$('helpContent').textContent='';$('formulaInput').value='';$('refsInput').value='';render();persist()}
function checkWin(){let last=state.lines.at(-1);if(last&&state.stack.length===0&&last.path.length===0&&Logic.eq(last.a,Logic.parse(problems[current].goal))){solved.add(problems[current].id);feedback('✓ 증명 완성! 수업에서 배운 규칙으로 목표를 도출했습니다.');renderList();persist()}}
$('addForm').onsubmit=e=>{e.preventDefault();try{let p=problems[current],next=Logic.add(state,$('formulaInput').value,$('ruleInput').value,$('refsInput').value,p.allowed);history.push(state);state=next;$('formulaInput').value='';$('refsInput').value='';feedback('✓ 올바른 단계입니다.');render();persist();checkWin();$('formulaInput').focus()}catch(err){feedback(err.message,'error')}};
$('closeAssumption').onclick=()=>{try{history.push(state);state=Logic.close(state);render();persist();feedback('가정을 닫았습니다. 닫힌 범위는 vE, <->I 또는 AC에서 사용할 수 있습니다.')}catch(err){history.pop();feedback(err.message,'error')}};
$('undo').onclick=()=>{if(history.length){state=history.pop();render();persist();feedback('직전 작업을 되돌렸습니다.')}};
$('reset').onclick=()=>{if(state.lines.length===problems[current].premises.length&&!state.stack.length)return;if(confirm('이 문제의 현재 증명을 지우고 다시 시작할까요?')){state=Logic.initial(problems[current].premises);history=[];render();persist();$('helpContent').textContent='';feedback('새 증명을 시작합니다.')}};
$('problemList').onclick=e=>{let b=e.target.closest('[data-id]');if(b)load(Number(b.dataset.id))};$('filters').onclick=e=>{let b=e.target.closest('[data-level]');if(!b)return;filter=b.dataset.level;document.querySelectorAll('[data-level]').forEach(x=>x.classList.toggle('selected',x===b));renderList()};$('sourceFilter').onchange=e=>{sourceFilter=e.target.value;renderList()};
document.querySelectorAll('[data-symbol]').forEach(b=>b.onclick=()=>{let f=$('formulaInput'),a=f.selectionStart,z=f.selectionEnd;f.setRangeText(b.dataset.symbol,a,z,'end');f.focus()});
$('hintBtn').onclick=()=>{$('helpContent').textContent=problems[current].hint};$('solutionBtn').onclick=()=>{let p=problems[current],n=p.premises.length;$('helpContent').innerHTML=`<b>예시 풀이 · ${p.solution.length}단계</b><p class="solution-note">가능한 풀이 중 하나입니다. 직접 작성한 증명은 그대로 유지됩니다.${p.note?' '+esc(p.note):''}</p>`+p.solution.map(([f,r,refs])=>r==='닫기'?'<div class="solution-note">↳ 가정 닫기</div>':`<div class="solution-row"><span>${++n}</span><span>${esc(Logic.format(Logic.parse(f)))}</span><span>${esc(r)} ${esc(refs)}</span></div>`).join('')};
$('nextBtn').onclick=()=>load((current+1)%problems.length);$('rulesNav').onclick=()=>$('rulesDialog').showModal();$('dialogClose').onclick=()=>$('rulesDialog').close();$('rulesDialog').onclick=e=>{if(e.target===$('rulesDialog')){let r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};$('practiceNav').onclick=()=>$('formulaInput').focus();$('problemList').addEventListener('keydown',e=>{if(e.key==='Enter')e.target.closest('[data-id]')?.click()});load(current);
